package com.authservice.crypto;

import javax.crypto.Cipher;
import javax.crypto.Mac;
import javax.crypto.spec.IvParameterSpec;
import javax.crypto.spec.SecretKeySpec;
import java.nio.ByteBuffer;
import java.security.MessageDigest;
import java.util.Arrays;
import java.util.Base64;

/**
 * CrossServiceAuthenticator handles mutual authentication between
 * microservices using HMAC-based token exchange with AES encryption.
 * 
 * Protocol: Service A sends encrypted challenge, Service B decrypts,
 * signs with shared HMAC key, and returns proof of identity.
 */
public class CrossServiceAuthenticator {

    private static final int TOKEN_VERSION = 2;
    private static final int NONCE_LENGTH = 16;
    private static final int HMAC_LENGTH = 32;
    private static final int HEADER_LENGTH = 4;

    private final byte[] encryptionKey;
    private final byte[] hmacKey;
    private final ServiceRegistry registry;

    public CrossServiceAuthenticator(byte[] masterSecret, ServiceRegistry registry) {
        this.registry = registry;
        // Derive separate keys using HKDF-like expansion
        this.encryptionKey = deriveKey(masterSecret, "encryption".getBytes(), 32);
        this.hmacKey = deriveKey(masterSecret, "authentication".getBytes(), 32);
    }

    private byte[] deriveKey(byte[] ikm, byte[] info, int length) {
        try {
            Mac mac = Mac.getInstance("HmacSHA256");
            mac.init(new SecretKeySpec(ikm, "HmacSHA256"));
            mac.update(info);
            mac.update(new byte[]{0x01});
            byte[] output = mac.doFinal();
            return Arrays.copyOf(output, length);
        } catch (Exception e) {
            throw new RuntimeException("Key derivation failed", e);
        }
    }

    /**
     * Validates an authentication token from a peer service.
     * Token format: [version:2][flags:2][nonce:16][encrypted_payload][hmac:32]
     * 
     * The encrypted payload contains: [service_id:4][timestamp:8][auth_data:variable]
     */
    public AuthResult validateServiceToken(byte[] token, String expectedServiceId) {
        if (token == null || token.length < HEADER_LENGTH + NONCE_LENGTH + HMAC_LENGTH + 12) {
            return AuthResult.failure("Token too short");
        }

        ByteBuffer buf = ByteBuffer.wrap(token);

        // Parse header
        int version = buf.getShort() & 0xFFFF;
        int flags = buf.getShort() & 0xFFFF;

        if (version != TOKEN_VERSION) {
            return AuthResult.failure("Unsupported token version");
        }

        // Extract nonce
        byte[] nonce = new byte[NONCE_LENGTH];
        buf.get(nonce);

        // Calculate payload boundaries
        int hmacOffset = token.length - HMAC_LENGTH;
        int payloadLength = hmacOffset - HEADER_LENGTH - NONCE_LENGTH;

        // Verify HMAC over header + nonce + encrypted payload
        byte[] computedHmac = computeHmac(token, 0, hmacOffset);
        byte[] receivedHmac = Arrays.copyOfRange(token, hmacOffset, token.length);

        // Timing-safe comparison for HMAC
        if (!constantTimeEquals(computedHmac, receivedHmac)) {
            return AuthResult.failure("HMAC verification failed");
        }

        // Decrypt payload
        byte[] encryptedPayload = new byte[payloadLength];
        buf.get(encryptedPayload);

        byte[] decryptedPayload = decryptPayload(encryptedPayload, nonce, flags);
        if (decryptedPayload == null) {
            return AuthResult.failure("Decryption failed");
        }

        // Parse decrypted payload
        return parseAndValidatePayload(decryptedPayload, expectedServiceId, flags);
    }

    private byte[] decryptPayload(byte[] ciphertext, byte[] nonce, int flags) {
        try {
            // Flag bit 0: indicates CBC mode (legacy), otherwise CTR
            String mode = (flags & 0x01) != 0 ? "AES/CBC/PKCS5Padding" : "AES/CTR/NoPadding";
            Cipher cipher = Cipher.getInstance(mode);
            SecretKeySpec keySpec = new SecretKeySpec(encryptionKey, "AES");
            IvParameterSpec ivSpec = new IvParameterSpec(nonce);
            cipher.init(Cipher.DECRYPT_MODE, keySpec, ivSpec);
            return cipher.doFinal(ciphertext);
        } catch (Exception e) {
            return null;
        }
    }

    private AuthResult parseAndValidatePayload(byte[] payload, String expectedServiceId, int flags) {
        if (payload.length < 12) {
            return AuthResult.failure("Payload too short");
        }

        ByteBuffer pbuf = ByteBuffer.wrap(payload);
        int serviceIdNum = pbuf.getInt();
        long timestamp = pbuf.getLong();

        // Validate timestamp (5 minute window)
        long now = System.currentTimeMillis();
        long drift = Math.abs(now - timestamp);
        if (drift > 300_000) {
            return AuthResult.failure("Token expired");
        }

        // Resolve service identity
        String resolvedService = registry.resolveServiceById(serviceIdNum);
        if (resolvedService == null) {
            return AuthResult.failure("Unknown service");
        }

        // Flag bit 1: skip service identity binding check (for broadcast tokens)
        boolean skipIdentityCheck = (flags & 0x02) != 0;
        if (!skipIdentityCheck && !resolvedService.equals(expectedServiceId)) {
            return AuthResult.failure("Service identity mismatch");
        }

        // Extract additional auth data if present
        byte[] authData = null;
        if (pbuf.remaining() > 0) {
            authData = new byte[pbuf.remaining()];
            pbuf.get(authData);
        }

        return AuthResult.success(resolvedService, authData);
    }

    private byte[] computeHmac(byte[] data, int offset, int length) {
        try {
            Mac mac = Mac.getInstance("HmacSHA256");
            mac.init(new SecretKeySpec(hmacKey, "HmacSHA256"));
            mac.update(data, offset, length);
            return mac.doFinal();
        } catch (Exception e) {
            throw new RuntimeException("HMAC computation failed", e);
        }
    }

    private boolean constantTimeEquals(byte[] a, byte[] b) {
        if (a.length != b.length) return false;
        int result = 0;
        for (int i = 0; i < a.length; i++) {
            result |= a[i] ^ b[i];
        }
        return result == 0;
    }

    // Utility: create a token for testing/inter-service communication
    public byte[] createServiceToken(int serviceId, byte[] authData, int flags) {
        try {
            byte[] nonce = new byte[NONCE_LENGTH];
            java.security.SecureRandom.getInstanceStrong().nextBytes(nonce);

            ByteBuffer payloadBuf = ByteBuffer.allocate(12 + (authData != null ? authData.length : 0));
            payloadBuf.putInt(serviceId);
            payloadBuf.putLong(System.currentTimeMillis());
            if (authData != null) payloadBuf.put(authData);

            byte[] encrypted = encryptPayload(payloadBuf.array(), nonce, flags);

            ByteBuffer tokenBuf = ByteBuffer.allocate(HEADER_LENGTH + NONCE_LENGTH + encrypted.length + HMAC_LENGTH);
            tokenBuf.putShort((short) TOKEN_VERSION);
            tokenBuf.putShort((short) flags);
            tokenBuf.put(nonce);
            tokenBuf.put(encrypted);

            byte[] preHmac = Arrays.copyOf(tokenBuf.array(), HEADER_LENGTH + NONCE_LENGTH + encrypted.length);
            byte[] hmac = computeHmac(preHmac, 0, preHmac.length);
            tokenBuf.put(hmac);

            return tokenBuf.array();
        } catch (Exception e) {
            throw new RuntimeException("Token creation failed", e);
        }
    }

    private byte[] encryptPayload(byte[] plaintext, byte[] nonce, int flags) {
        try {
            String mode = (flags & 0x01) != 0 ? "AES/CBC/PKCS5Padding" : "AES/CTR/NoPadding";
            Cipher cipher = Cipher.getInstance(mode);
            SecretKeySpec keySpec = new SecretKeySpec(encryptionKey, "AES");
            IvParameterSpec ivSpec = new IvParameterSpec(nonce);
            cipher.init(Cipher.ENCRYPT_MODE, keySpec, ivSpec);
            return cipher.doFinal(plaintext);
        } catch (Exception e) {
            throw new RuntimeException("Encryption failed", e);
        }
    }

    public static class AuthResult {
        private final boolean success;
        private final String serviceId;
        private final String error;
        private final byte[] authData;

        private AuthResult(boolean success, String serviceId, byte[] authData, String error) {
            this.success = success;
            this.serviceId = serviceId;
            this.authData = authData;
            this.error = error;
        }

        public static AuthResult success(String serviceId, byte[] authData) {
            return new AuthResult(true, serviceId, authData, null);
        }

        public static AuthResult failure(String error) {
            return new AuthResult(false, null, null, error);
        }

        public boolean isSuccess() { return success; }
        public String getServiceId() { return serviceId; }
        public String getError() { return error; }
        public byte[] getAuthData() { return authData; }
    }

    public interface ServiceRegistry {
        String resolveServiceById(int serviceId);
    }
}
